int normalize(int values[], int count) {
    int index = 0;                 // ①
    while (index < count) {        // ②
        if (values[index] < 0) {   // ③
            values[index] = -values[index]; // ④
        }
        index++;                   // ⑤
    }
    return 1;                      // ⑥
}

public class Main {
    static int search(int[] data,int start,int end){
        if(start>=end) return 0;
        int middle=(start+end)/2;
        return data[middle] + Math.max(
            search(data,start,middle),
            search(data,middle+1,end)
        );
    }
    public static void main(String[] args){
        int[] data={3,5,8,12,17};
        System.out.println(search(data,0,data.length-1));
    }
}

