#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

void reverse(int *arr, int n) {
    int *left = &arr[0];
    int *right = &arr[n - 1];
    while (left < right) {
        swap(left, right);
        left++;
        right--;
    }
}

int main(void) {
    int arr[] = {1, 2, 3, 4, 5};
    reverse(arr, 5);
    printf("%d", arr[2]);
    return 0;
}

